"""Build approved Stage B state index, reference sheets and original reusable asset exports."""
from pathlib import Path
import json,re
P=Path(__file__).resolve().parent;games=json.loads((P/'games.json').read_text())
shared=[('waiting','Waiting / transition','No eligible game view yet; existing room transition','Waiting for the next turn to begin.','Keep focus on the route heading; do not autofocus a game control.'),('active','Active play','The illustrated eligible local participant view','The approved active composition.','Preserve local input focus across timer/state refreshes.'),('spectator','Spectator','No participating local index / spectator role','You are watching. Private information stays private.','Heading then public board/ledger; no private inputs in the tab order.'),('invalid','Invalid / unavailable','Known local constraint or existing authoritative notice','Choose an available action.','Keep focus on the originating control/input; associate the inline reason.'),('reconnect','Reconnect / resync','Socket disconnected or room state not yet restored','Reconnecting… Your controls return when you are connected.','Keep focus stable; do not move to a disabled game control.'),('result','Win / results · host','Actual room result, local host; never a guessed timer outcome','Results are in. Your party stays together.','Result heading; then existing host result actions.'),('rematch','Result · participant','Actual result; participating non-host','Ready for another round?','Result heading; Ready for Rematch toggles aria-pressed; retain focus.')]
extra={
'drawguess':[('choose','Six-word choice','Drawer and phase=choose; choices has six words','Choose your word.','First word button; two columns; no word content for other roles.'),('guesser','Guesser / masked word','phase=draw and local eligible guesser has not guessed','Nova is drawing · six-letter mask.','Guess input; never drawer tools.'),('guessed','Guessed correctly','Local ID in guessed; server view now permits word','You got it. Let the others guess.','Success receipt; keep chat focus; no further scoring guesses.'),('reveal','Round reveal','phase=reveal; turnResult and word present','The word was DRAGON.','Reveal heading; do not invent Next button or end the round locally.'),('focus','Canvas focus mode','Existing expanded drawing view','More room for the drawing.','Exit Focus visible; Escape returns focus to original expand control.'),('clear','Clear confirmation','Local clear intent; no clear action sent yet','Clear the whole drawing?','Use existing confirmation behavior; custom dialog is a presentation proposal requiring parity tests.')],
'fourrow':[('opponent','Opponent turn','turn differs from myIndex','Nova is up. You are Red.','Read-only board; turn announcement once, not every tick.'),('full','Full column','Six occupied slots in a column','Column 1 is full. Choose another.','Full column is unavailable; keep an accessible reason.'),('draw','Draw result','Actual result.draw','Board full. It’s a draw.','Result heading; neutral palette and existing result actions.')],
 'tictactoe':[('opponent','Opponent turn','turn differs from myIndex','Nova is choosing a square.','Read-only board; keep prior focus stable.'),('draw','Draw result','Actual result.draw','Nine marks. No line. A draw.','Neutral result heading; no victory celebration.')],
'rps':[('locked','Private pick locked','myPick present, phase=pick','Rock locked. Waiting for Nova.','Selected throw unavailable; lock receipt role=status.'),('reveal','Simultaneous reveal','phase=reveal and reveal.results present','Rock beats scissors. Alex wins the throw.','Announce both throws and outcome together.'),('tie','Tie / throw again','reveal.out=tie','Both chose Rock. Throw again.','Wait for new phase=pick before enabling choices.'),('bye','Bye / waiting','Not in current live match, eligible player','You have a bye. Watch the bracket.','Bracket region; no private throw controls.'),('bracket16','Sixteen-player bracket','Existing bracket with four rounds','The whole tournament at a glance.','Scrollable named bracket region, keyboard reachable.'),('out','Eliminated','players[myIndex].out or left','You’re out. Follow the final.','Bracket only; no picker.')],
'dotsboxes':[('opponent','Opponent turn','turn differs from myIndex','Nova is choosing an edge.','Disable playable edges; public owner initials remain.'),('claim','Box / extra turn','Accepted edge closes one or more boxes and local turn remains','Box claimed. You go again.','Keep focus on last edge or next legal edge, not a full rerender reset.'),('dense','Largest supported grid','n=5 from existing settings','More boxes, the same clear targets.','Precision/keyboard edge input supplements dense direct targets.')],
'wordscramble':[('solved','Solved / locked','solvedByMe true','Solved · +90. Waiting for the others.','Success receipt; do not expose answer to other participants.'),('reveal','Answer reveal','phase=reveal and reveal.word exists','The word was OCEAN.','Announce reveal once with actual gain/no-answer outcome.'),('long','Long word / wrapping','Existing hard length; same typed-answer rules','Keep every letter readable.','Normal input, not drag-only tiles.')],
 'trivia':[('locked','Answer locked','phase=ask and myPick not null','Himalayas locked. Waiting for the others.','Selected answer aria-pressed, no change after lock.'),('reveal','Correct answer / gain','phase=reveal and reveal.correct exists','Correct · +180. Himalayas.','Correct label plus symbol/outline; keyboard focus remains stable.'),('wrong','Wrong / no-answer reveal','phase=reveal and local wrong or absent pick','Not this time. The answer is Himalayas.','Mark local wrong separately from the revealed correct answer.'),('long','Long question / answers','Existing variable-length question and choices','Long text wraps without reducing answer targets.','Keep each choice fully readable and touchable.')],
 'wordchain':[('opponent','Opponent turn','turnId differs from local ID','Nova’s turn · start with R.','Disable local word form; preserve draft if policy allows.'),('life','Life lost / new turn','Accepted server lives/turn change after timeout','One life lost. Nova is up.','Announce lives and next turn once; do not restart the deadline.'),('deadletter','New chain start','Server clears chain / first becomes true','A fresh start. Begin with A.','Focus input only on a newly eligible local turn.'),('out','Out / watching','Local lives is zero','You’re out. Watch the chain continue.','Remove actionable word input; preserve public chain/history.')],
'categories':[('locked','Done / read-only','myDone true','Your answers are locked. Waiting for the others.','Fields readOnly; Done disabled; confirmation receipt remains.'),('review','Round answer review','phase=review and review.rows exists','Unique 2 · matching 1 · invalid 0.','Named review region/table; horizontal scrolling stays inside it.'),('autosave','Draft pending','Local debounce/send without final done','Saving your draft…','Never move focus or replace the active input node.'),('long','Long category / keyboard','Long category names from existing bank','The label wraps. Your answer stays editable.','Focus and caret survive; controls remain reachable above the keyboard.')],
 'telephone':[('prompt','Initial prompt','phase=work, kind=prompt','Write something fun to draw.','Prompt input then Submit; no source/chain entries yet.'),('describe','Describe source drawing','phase=work, kind=guess and source.kind=draw','What is this a drawing of?','Description input; only this source drawing is shown.'),('pending','Done awaiting acceptance','Local send, myDone still false','Submitting… Your page is not locked yet.','Keep draft/strokes until actual myDone or existing rejection handling.'),('locked','Done accepted','myDone true','Page passed. Waiting for the others.','No editable drawing/text; receipt focus stable.'),('reveal','Staged chain reveal','phase=reveal and rev.entries contains released prefix','One story, wonderfully changed.','Only returned entries; Like disabled for own/skipped/already-liked.'),('limit','Drawing limit','Existing stroke/fill/point cap reached locally','Drawing limit reached. Undo or clear to continue.','Keep Undo/Clear reachable; explain the limit beside canvas.')],
 'bluff':[('write','Write a bluff','phase=bluff, eligible, myFake absent','Make it believable.','Fake-answer input max 40, Submit explicit.'),('locked','Bluff locked','myFake present in bluff phase','Your bluff is in. Waiting for the others.','Show own text only; remove editable input.'),('voted','Vote locked','phase=vote, myVote not null','Gridmark locked. Waiting for the truth.','Own selected option is named, all vote inputs unavailable.'),('reveal','Truth / authors / voters','phase=reveal; reveal.options returned','Octothorpe was the real answer.','Reveal real flag, merged authors and voters only now.')],
 'impostor':[('impostor','Private impostor role','role=impostor, word null','You are the impostor. Blend in.','Category only; no secret word in DOM/labels/data.'),('covered','Private word covered','Local cover preference while crew view permits word','Word covered.','Local privacy cover; button toggles aria-expanded; not a security boundary.'),('opponent','Another player’s clue','phase=clue and turnId differs from local','Waiting for Nova’s clue.','Own clue form unavailable; public clues readable.'),('discuss','Discussion / ready','phase=discuss','Who doesn’t know the word?','Discussion chat plus existing ready action; no voice feature.'),('vote','Accusation vote','phase=vote and myVote absent','Who is the impostor?','Equal public player targets; own target unavailable.'),('voted','Vote locked','myVote present','Vote locked. Waiting for the others.','Private selected target only; no public counts before result.'),('lastguess','Caught impostor / guess','phase=guess and role=impostor','One last chance. Guess the word.','Word remains unknown; guess input for impostor only.'),('reveal','Round result / word','phase=result and result exists','Nova was the impostor. The word was CANDLE.','Use actual caught/stole/voided result, not inferred votes.')],
 'checkers':[('opponent','Opponent turn','turn differs from myIndex','Nova is choosing a move.','No legal targets for local non-turn view.'),('capture','Mandatory capture','mustJump true and legal targets present','You must capture.','Only real movable pieces/targets enabled.'),('chain','Locked multi-jump','chain >= 0','Keep jumping with the same piece.','Chain piece stays selected; focus next permitted destination.'),('king','King crowned','Accepted board piece >= 3','Your piece is now a king.','Crown plus named piece; do not infer kings from decorative size.'),('resign','Resign armed','Existing makeConfirm armed state','Tap again to resign.','Stable two-tap confirmation survives re-render; no resign on first tap.'),('draw','Quiet draw','Actual draw result, not local quiet counter alone','A draw · no capture or man move for 40 moves each.','Neutral result and actual final board.')]
}
models=[]
for g in games:
 states=[dict(zip(['id','label','trigger','copy','focus'],row)) for row in shared+extra[g['id']]]
 models.append({**g,'states':states})
(P/'state-model.json').write_text(json.dumps(models,indent=2)+'\n')
# Reusable, original vector exports, independent from example drawing illustrations.
icons={'mark-x':('<path d="M18 18L78 78M78 18L18 78"/>','#517f9b',18,96),'mark-o':('<circle cx="48" cy="48" r="31"/>','#d78073',16,96),'crown':('<path d="M3 19L2 7l6 5 4-8 4 8 6-5-1 12Z"/>','#274d40',1.5,24),'check':('<path d="M4 12l5 5L20 5"/>','#cae997',2.5,24),'cross':('<path d="M6 6l12 12M18 6L6 18"/>','#f2b5a4',2.5,24),'connection':('<path d="M4 10q8-9 16 0M7 13q5-5 10 0M10 16q2-2 4 0"/><circle cx="12" cy="20" r="1"/>','#c5d5d0',1.8,24),'trophy':('<path d="M7 3h10v6q0 6-5 6T7 9Zm0 2H3v3q0 4 5 4m9-7h4v3q0 4-5 4m-4 3v5m-5 1h10"/>','#e9d396',1.8,24),'pencil':('<path d="M4 20l1-6L16 3l5 5-11 11Zm10-15 5 5M5 14l5 5"/>','#d9e6d5',1.8,24),'eraser':('<path d="M3 14 13 3l8 8-10 10H9ZM8 20h13M8 9l8 8"/>','#d9e6d5',1.8,24),'fill':('<path d="m4 8 9-5 7 10-10 7-7-9ZM6 6l12 10m2 2q4 5 0 5-4 0 0-5"/>','#d9e6d5',1.8,24),'undo':('<path d="m8 5-5 5 5 5M3 10h10q9 0 7 8"/>','#d9e6d5',1.8,24),'clear':('<path d="M4 7h16M9 4h6M7 8l1 13h8l1-13M10 11v6m4-6v6"/>','#d9e6d5',1.8,24)}
for n,(body,c,w,size) in icons.items():
 (P/'assets'/f'{n}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {size} {size}" role="img"><title>Playgrid original {n}</title><g fill="none" stroke="{c}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg>')
style='''<style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#071722;color:#edf2eb;font:14px Arial,sans-serif}h1{font-size:26px;margin:8px 0}p{color:#b6c9c7;font-size:12px;line-height:1.6}a{color:#c9ef9b}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.state{border:1px solid #35535e;background:#0c2230;border-radius:10px;padding:12px;min-width:0}.state h2{font-size:16px;margin:0 0 8px}.state p{font-size:11px;margin:8px 0}.viewport{position:relative;overflow:hidden;margin:auto;background:#04111b}.viewport iframe{border:0;position:absolute;top:0;left:0;transform-origin:0 0} .mobile .grid{grid-template-columns:repeat(3,minmax(0,1fr))}</style>'''
for g in models:
 for mode,w,h,scale in [('desktop',1440,900,.475),('mobile',390,844,.92)]:
  s=f'<!doctype html><html lang="en"><meta charset="utf-8"><link rel="icon" href="data:,"><title>{g["name"]} · state sheets</title>{style}<body class="{mode}"><p>PLAYGRID / ISSUE #55 / APPROVED DIRECTIONS / STAGE B · DESIGN REFERENCES</p><h1>{g["name"]} · {g["direction"]}</h1><p>{w}×{h} state frames. Illustrative static content, not live multiplayer or implementation evidence. <a href="../state-explorer.html?game={g["id"]}">Open full-size explorer</a>.</p><div class="grid">'
  for st in g['states']:
   s+=f'<article class="state"><h2>{st["label"]}</h2><div class="viewport" style="width:{w*scale}px;height:{h*scale}px"><iframe title="{st["label"]}" src="concept.html?state={st["id"]}" width="{w}" height="{h}" style="transform:scale({scale})" loading="eager"></iframe></div><p>{st["trigger"]}</p></article>'
  s+='</div></body></html>';(P/g['id']/f'states-{mode}.html').write_text(s)
# Inspector controls are local design navigation, not game controls.
explorer='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>Playgrid · approved state explorer</title><style>*{box-sizing:border-box}body{margin:0;background:#071722;color:#edf2eb;font:14px Arial}nav{padding:16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}select,button{padding:10px;background:#16313e;color:#eff5e9;border:1px solid #53717c;border-radius:6px}p{padding:0 16px;color:#b6c9c7;font-size:12px}#frame{overflow:auto;padding:16px}iframe{border:1px solid #42616c;display:block}label{display:flex;align-items:center;gap:7px}</style><nav><b>APPROVED DESIGN REFERENCE</b><label>Game <select id="game"></select></label><label>State <select id="state"></select></label><label>Viewport <select id="size"><option value="1440,900">Desktop · 1440×900</option><option value="390,844">Phone · 390×844</option><option value="360,740">Narrow · 360×740</option><option value="390,520">Keyboard viewport · 390×520</option></select></label><label><input id="motion" type="checkbox"> Reduced motion preview</label></nav><p>Fixed design examples. Changing these selectors does not play a game or connect to Socket.IO.</p><p id="note"></p><div id="frame"><iframe id="preview" title="Game state design reference"></iframe></div><script>
fetch('state-model.json').then(r=>r.json()).then(games=>{const g=document.querySelector('#game'),s=document.querySelector('#state'),z=document.querySelector('#size'),p=document.querySelector('#preview'),m=document.querySelector('#motion');g.innerHTML=games.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');g.value=new URLSearchParams(location.search).get('game')||games[0].id;function draw(){const x=games.find(x=>x.id===g.value),st=x.states.find(x=>x.id===s.value)||x.states[0],[w,h]=z.value.split(',');p.width=w;p.height=h;p.src=x.id+'/concept.html?state='+st.id+(m.checked?'&reduced=1':'');document.querySelector('#note').textContent=st.trigger+' · '+st.focus;}function pick(){const x=games.find(x=>x.id===g.value);s.innerHTML=x.states.map(st=>`<option value="${st.id}">${st.label}</option>`).join('');s.value='active';draw();}g.onchange=pick;s.onchange=draw;z.onchange=draw;m.onchange=draw;pick();});</script></html>'''
(P/'state-explorer.html').write_text(explorer)
print('Stage B state index:',sum(len(x['states']) for x in models),'frames; 26 sheet sources; 12 reusable SVG exports.')
